func (s R10ConvInputs) JSONSize() int {
	size := 45
	size += len(s.Label) * 2
	size += s.Named.JSONSize()
	size += s.Ptr.JSONSize()
	size += s.Text.JSONSize()
	size += s.TextP.JSONSize()
	return size
}

func (s R10ConvInputs) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"label\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Label)
	dst = append(dst, ",\"named\":"...)
	if dst, err = s.Named.AppendJSON(dst); err != nil {
		return dst, err
	}
	dst = append(dst, ",\"ptr\":"...)
	if dst, err = s.Ptr.AppendJSON(dst); err != nil {
		return dst, err
	}
	dst = append(dst, ",\"text\":"...)
	if dst, err = s.Text.AppendJSON(dst); err != nil {
		return dst, err
	}
	dst = append(dst, ",\"textp\":"...)
	if dst, err = s.TextP.AppendJSON(dst); err != nil {
		return dst, err
	}
	return append(dst, '}'), nil
}

